<?php session_start();require_once __DIR__.'/../db.php';if(empty($_SESSION['user_id'])||($_SESSION['role']??'')!=='admin'){header('Location: ../login.php');exit;}if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf_token'],$_POST['csrf_token']??'')){$err='Security check failed. Refresh and try again.';}else{$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$role=$_POST['role']??'';if($name===''||$username===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!in_array($role,['storekeeper'],true))$err='Complete all fields. Password must be at least 8 characters.';else{$c=$conn->prepare('SELECT id FROM users WHERE username=? OR email=?');$c->bind_param('ss',$username,$email);$c->execute();if($c->get_result()->num_rows)$err='Username or email already exists.';else{$hash=password_hash($password,PASSWORD_DEFAULT);$i=$conn->prepare('INSERT INTO users(full_name,username,email,password,role) VALUES(?,?,?,?,?)');$i->bind_param('sssss',$name,$username,$email,$hash,$role);$msg=$i->execute()?'Staff account created successfully.':'Could not create account.';$i->close();}}}}$staff=$conn->query("SELECT id,full_name,username,email,role,is_active FROM users WHERE role='storekeeper' ORDER BY full_name");?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff Management</title><link rel="stylesheet" href="../assets/css/modern.css"></head><body><main class="page"><header class="topbar"><div><a class="brand" href="dashboard.php">Fresh<span>Mart</span></a><h1>Staff management</h1><p class="muted">Create and manage Storekeeper accounts. Customers register separately.</p></div><a class="btn" href="dashboard.php">Admin dashboard</a></header><section class="panel"><h2>Create staff account</h2><?php if($msg):?><div class="alert success"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><div><label>Full name</label><input name="full_name" required></div><div><label>Username</label><input name="username" required></div><div><label>Email</label><input type="email" name="email" required></div><div><label>Temporary password</label><input type="password" name="password" minlength="8" required></div><div><label>Role</label><select name="role" required><option value="storekeeper">Storekeeper</option></select></div><div style="align-self:end"><button class="btn primary">Create account</button></div></form></section><section class="panel" style="margin-top:18px"><h2>Existing staff</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($staff)while($r=$staff->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['username'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><span class="badge"><?=htmlspecialchars($r['role'])?></span></td><td><?=((int)$r['is_active']===1?'Active':'Inactive')?></td><td><a class="btn" href="edit_staff.php?id=<?=(int)$r['id']?>">Edit</a></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>
